(function (H) {
  var idx = null;
  H.byId = function (id) {
    if (!idx) { idx = {}; for (var i = 0; i < H.rows.length; i++) idx[H.rows[i].id] = i; }
    var k = idx[id]; return k == null ? null : H.rows[k];
  };
  /* tel: link only for a number with an area code (D18) */
  H.telHref = function (row) {
    var c = row && row.contact; if (!c || !c.phone || c.phoneNoArea) return null;
    var d = String(c.phone).replace(/[^\d+]/g, '');
    return /^\+?\d{7,15}$/.test(d) ? 'tel:' + d : null;
  };
  /* website link only when checked and open (D17) */
  H.webLink = function (row) {
    var c = row && row.contact; if (!c || !c.web) return null;
    return (c.webCheck === 'ok' || c.webCheck === 'dialihkan' || c.webCheck === 'belum') ? c.web : null;
  };
})(window.MCD_HEALTH_FACILITIES);
